<script setup lang="ts">
import { friendlyError } from '@lostsky/api/client'; import LsButton from '@lostsky/ui/components/LsButton.vue'; import LsField from '@lostsky/ui/components/LsField.vue'; import LsInlineError from '@lostsky/ui/components/LsInlineError.vue'; import LsPageHeader from '@lostsky/ui/components/LsPageHeader.vue'; import LsPanel from '@lostsky/ui/components/LsPanel.vue'; import { feedback } from '@lostsky/ui/feedback'; import { useMutation,useQuery } from '@tanstack/vue-query'; import { NInput,NInputNumber,NSelect,NSwitch,useDialog } from 'naive-ui'; import { computed,reactive,watch } from 'vue'; import { useRoute,useRouter } from 'vue-router'; import { canManage,manageApi } from '../../lib'
const route=useRoute();const router=useRouter();const dialog=useDialog();const id=computed(()=>Number(route.params.id||0));const editing=computed(()=>id.value>0);const form=reactive({name:'',description:'',default_total_price:0,default_cost:0,default_handler_cut:0,default_sender_cut:0,default_cs_cut:0,default_team_cut:0,is_active:1,handler_entity_ids:[] as number[]});const options=useQuery({queryKey:['manage-options'],queryFn:manageApi.options});const detail=useQuery({queryKey:computed(()=>['manage-service',id.value]),queryFn:()=>manageApi.service(id.value),enabled:editing});watch(()=>detail.data.value,d=>{if(d)Object.assign(form,d,{handler_entity_ids:(d.handlers??[]).map(h=>h.entity_id)})},{immediate:true});const entityOptions=computed(()=>(options.data.value?.entities??[]).map(e=>({label:e.name,value:Number(e.entity_id??e.id)})));const save=useMutation({mutationFn:()=>manageApi.saveService(editing.value?id.value:null,form),onSuccess:data=>{feedback.success('服务已保存');router.push(`/manage/services/${data.id}`)}});const disable=useMutation({mutationFn:()=>manageApi.disableService(id.value),onSuccess:()=>router.push('/manage/services')});function stop(){dialog.warning({title:'停用服务',content:'停用后不能加入新的权益配置；历史服务实例不受影响。',positiveText:'确认停用',negativeText:'返回',onPositiveClick:()=>disable.mutate()})}const valid=computed(()=>Boolean(form.name.trim()))
</script><template><div class="manage-page"><LsPageHeader :title="editing?'编辑服务':'新建服务'" description="默认金额会冻结到卡密交付的每个独立服务实例。" back-to="/manage/services" back-label="返回服务"><template #actions><LsButton v-if="editing&&canManage('shop.product.delete')" variant="danger" @click="stop">停用服务</LsButton></template></LsPageHeader><form class="manage-form" @submit.prevent="save.mutate()"><LsPanel><div class="form-panel"><h2>基本信息</h2><LsField label="服务名称" for-id="service-name" required><NInput id="service-name" v-model:value="form.name" maxlength="100"/></LsField><LsField label="说明" for-id="service-description"><NInput id="service-description" v-model:value="form.description" type="textarea" maxlength="1000" show-count/></LsField><LsField label="启用状态" for-id="service-active"><NSwitch id="service-active" :value="form.is_active===1" @update:value="v=>form.is_active=v?1:0"/></LsField><LsField label="默认接单人" for-id="service-handlers" hint="Customer 发起核销时只能从该接单池选择。"><NSelect id="service-handlers" v-model:value="form.handler_entity_ids" :options="entityOptions" multiple filterable clearable placeholder="选择一个或多个 Entity"/></LsField></div></LsPanel><LsPanel><div class="form-panel"><h2>默认金额与分配</h2><p class="form-intro">仅用于服务卡领取；服务包订单会使用订单自身冻结的金额。</p><LsField label="单次服务价值" for-id="service-price"><NInputNumber id="service-price" v-model:value="form.default_total_price" :min="0" :precision="2"/></LsField><LsField label="成本" for-id="service-cost"><NInputNumber id="service-cost" v-model:value="form.default_cost" :min="0" :precision="2"/></LsField><LsField label="接单分配" for-id="service-handler-cut"><NInputNumber id="service-handler-cut" v-model:value="form.default_handler_cut" :min="0" :precision="2"/></LsField><LsField label="发单分配" for-id="service-sender-cut"><NInputNumber id="service-sender-cut" v-model:value="form.default_sender_cut" :min="0" :precision="2"/></LsField><LsField label="客服分配" for-id="service-cs-cut"><NInputNumber id="service-cs-cut" v-model:value="form.default_cs_cut" :min="0" :precision="2"/></LsField><LsField label="团队分配" for-id="service-team-cut"><NInputNumber id="service-team-cut" v-model:value="form.default_team_cut" :min="0" :precision="2"/></LsField></div></LsPanel><LsInlineError v-if="detail.isError.value" :message="friendlyError(detail.error.value)"/><LsInlineError v-if="save.isError.value" :message="friendlyError(save.error.value)"/><div class="form-actions"><LsButton type="button" variant="secondary" @click="router.back()">取消</LsButton><LsButton type="submit" :disabled="!valid||!canManage('shop.product.write')" :loading="save.isPending.value">保存服务</LsButton></div></form></div></template>
